    local function cleanupFly()
        for _, conn in ipairs(flyConnections) do
            pcall(function() conn:Disconnect() end)
        end
        flyConnections = {}
        for _, inst in ipairs(flyInstances) do
            pcall(function() inst:Destroy() end)
